      "description": "La SÍNTESIS ORGÁNICA EN LA INDUSTRIA dota de conocimientos básicos para la síntesis y aplicación de distintos compuestos orgánicos industriales a través del uso de los principios de la Química Orgánica, así como sus principales rutas de síntesis, procesos industriales y aplicaciones tecnológicas. Enmarcado en el respeto y compromiso por el cuidado del medio ambiente. La asignatura aporta al Perfil de Egreso del Ingeniero Químico en lo siguiente: Reconocer el valor de los saberes ancestrales, posibilitando su incorp",
