      "description": "La asignatura de Química General, se imparte en el primer semestre de la Carrera de Ingeniería Química. Con esta asignatura, junto con la Química Inorgánica se pretende, esencialmente que el estudiante profundice en los conocimientos de química adquiridos en el colegio, en determinados aspectos y los complemente. De esta manera, se establecerán los fundamentos imprescindibles para que el estudiante transmita con éxito estudios posteriores. En concreto, en esta signatura se abordarán elementos básicos como enlaces q",
