      "description": "Las prácticas pre profesionales y pasantías en las carreras de tercer nivel son actividades de aprendizaje orientadas a la aplicación de conocimientos y/o al desarrollo de competencias profesionales. Estas prácticas se realizarán en entornos organizacionales, institucionales, empresariales, comunitarios u otros relacionados al ámbito profesional de cada carrera, público o privado, nacional o internacional. Las prácticas pre profesionales se subdividen en dos componentes: Prácticas laborales, de naturaleza profesion",
