      "description": "La asignatura de Química Analítica corresponde al área de formación profesional de la Carrera de Ingeniería Química la misma que es de naturaleza teórica práctica. La química analítica puede definirse como la ciencia que desarrolla y mejora métodos e instrumentos para obtener información sobre la composición y naturaleza química de la materia. Dentro de la química analítica se incluye el Análisis Cuantitativo que es la parte práctica que aplica los métodos de análisis para resolver problemas relativos a la composic",
